document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("loginForm"),e=document.getElementById("loginEmail"),n=document.getElementById("loginPassword"),o=document.getElementById("loginEmailError"),d=document.getElementById("loginPasswordError");t.addEventListener("submit",l=>{let r=!0;var m;if(e.value.trim()?(m=e.value.trim(),/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(m)?o.textContent="":(o.textContent="صيغة البريد الإلكتروني غير صحيحة",r=!1)):(o.textContent="يرجى إدخال البريد الإلكتروني",r=!1),n.value?d.textContent="":(d.textContent="يرجى إدخال كلمة المرور",r=!1),!r)return void l.preventDefault();const i=t.querySelector('button[type="submit"]');i.disabled=!0,i.textContent="جارِ تسجيل الدخول ..."})});